import { Colors, TextSize } from "shared/styles";
import { tokenizeLinks } from "shared/utils";

interface Props {
  body: string;
  isUser: boolean;
}

const handleLinkPress = (url: string) => {
  Linking.openURL(url).catch(() => {});
};

export const LinkifiedText: FC<Props> = ({ body, isUser }) => {
  const tokens = tokenizeLinks(body);

  return (
    <Text size={TextSize.small} color="white">
      {tokens.map((token, i) => {
        if (token.type === "link") {
          return (
            <Text
              key={i}
              color={isUser ? Colors.white : Colors.primary}
              style={styles.link}
              onPress={() => handleLinkPress(token.value)}
            >
              {token.value}
            </Text>
          );
        }
        return token.value;
      })}
    </Text>
  );
};

const styles = StyleSheet.create({
  link: {
    textDecorationLine: "underline",
  },
});

